fun main() {
    // named groups
    val date = Regex("(?<year>\\d{4})-(?<month>\\d{2})-(?<day>\\d{2})")
    val m = date.find("on 2024-03-15 and 2025-12-01")!!
    println(m.value + " " + m.range)
    println(m.groups["year"]!!.value + "/" + m.groups["month"]!!.value + "/" + m.groups["day"]!!.value)
    println(m.groups["year"]!!.range)
    println(m.groupValues)
    println(m.groups.size)
    val (y, mo, d) = m.destructured
    println("$y $mo $d")
    println(m.next()!!.value)
    println(m.next()!!.next())
    println(date.replace("2024-03-15", "${'$'}{day}.${'$'}{month}.${'$'}{year}"))
    println(date.replace("2024-03-15", "$3/$2/$1"))
    val named = Regex("(?<a>x)|(?<b>y)")
    val mm = named.find("y")!!
    println(mm.groups["a"])
    println(mm.groups["b"]?.value)
    println(mm.groups[1])
    println(mm.groupValues)
    try {
        mm.groups["zzz"]
    } catch (e: IllegalArgumentException) {
        println("no such group")
    }
    // backreferences by name
    println(Regex("(?<q>['\"]).*?\\k<q>").find("say 'hi' and \"yo\"")!!.value)
    println(Regex("(\\w)\\1").findAll("aabbcd eef").map { it.value }.toList())
    // lookahead / lookbehind
    println(Regex("\\w+(?=@)").find("user@example.com")!!.value)
    println(Regex("(?<=@)\\w+").find("user@example.com")!!.value)
    println(Regex("(?<!\\d)\\d{2}(?!\\d)").findAll("1 22 333 44 5555 66").map { it.value }.toList())
    println(Regex("foo(?!bar)").findAll("foobar foobaz foo").map { it.range.first }.toList())
    println(Regex("(?<=\\$)\\d+(\\.\\d\\d)?").findAll("cost \$15.50 or \$7 or 8").map { it.value }.toList())
    println(Regex("(?<=ab|c)d").findAll("abd cd xd").map { it.range.first }.toList())
    println("1234567".replace(Regex("(?<=\\d)(?=(\\d{3})+$)"), ","))
    println(Regex("^(?=.*\\d)(?=.*[a-z])(?=.*[A-Z]).{8,}$").matches("Passw0rdX"))
    println(Regex("^(?=.*\\d)(?=.*[a-z])(?=.*[A-Z]).{8,}$").matches("password"))
    // replace with lambda
    println(Regex("\\d+").replace("a1b22c333") { (it.value.toInt() * 2).toString() })
    println(Regex("[aeiou]").replace("education") { it.value.uppercase() })
    println(Regex("(\\w+)@(\\w+)").replace("me@home you@work") { "${it.groupValues[2]}@${it.groupValues[1]}" })
    println("hello world".replace(Regex("\\b\\w")) { it.value.uppercase() })
    println(Regex("x").replace("axbxc") { "" })
    println(Regex("").replace("abc") { "-" })
    println(Regex("a*").replace("baaac", "X"))
    println(Regex("\\d").replace("a1b2", "[$0]"))
    println(Regex("(a)(b)?").replace("ab a", "<$1|$2>"))
    println(Regex("a").replace("aaa", "\\$"))
    println(Regex("a").replace("aaa", Regex.escapeReplacement("$1\\")))
    println(Regex("a").replaceFirst("aaa", "b"))
    println("a.b.c".replace(".", "-"))
    println("a.b.c".replace(Regex("\\."), "-"))
    println("abcabc".replaceFirst(Regex("b"), "X"))
    // split with limit
    println(Regex(",").split("a,b,c,d"))
    println(Regex(",").split("a,b,c,d", 2))
    println(Regex(",").split("a,b,c,d", 3))
    println(Regex(",").split("a,b,c,d", 0))
    println(Regex(",").split("a,b,c,d", 10))
    println(Regex(",").split("a,,b,,"))
    println(Regex(",").split(",a"))
    println(Regex("\\s+").split("  a  b   c "))
    println(Regex("\\s*").split("a b"))
    println(Regex("").split("abc"))
    println(Regex("(,)").split("a,b"))
    println("a1b2c3".split(Regex("\\d")))
    println("a1b2c3".split(Regex("\\d"), 2))
    println("a1b2c3".split(Regex("\\d"), 0))
    println("a b  c".split(Regex(" ")).size)
    println(Regex(",").splitToSequence("a,b,c").toList())
    println("a,b,c".splitToSequence(Regex(",")).toList())
    try {
        Regex(",").split("a", -1)
    } catch (e: IllegalArgumentException) {
        println("neg limit")
    }
    // findAll
    println(Regex("\\d+").findAll("a1 b22 c333").map { it.value }.toList())
    println(Regex("\\d+").findAll("a1 b22 c333", 4).map { it.value }.toList())
    println(Regex("\\d+").findAll("nothing").count())
    println(Regex("a?").findAll("baab").map { it.range }.toList())
    println(Regex("").findAll("ab").map { it.range }.toList())
    println(Regex("\\b").findAll("ab cd").map { it.range.first }.toList())
    println(Regex("(\\d)(\\w)?").findAll("1a 2 3b").map { it.groupValues }.toList())
    println(Regex("(\\d)(\\w)?").findAll("1a 2 3b").map { it.groups[2]?.value }.toList())
    println(Regex("o").findAll("foo boo").map { it.range.first }.toList())
    println(Regex("\\w+").findAll("The quick brown fox").joinToString("|") { it.value })
    println(Regex("[a-z]+").findAll("ab1cd2ef").sumOf { it.value.length })
    // find / matches
    println(Regex("b+").find("abbbc")!!.range)
    println(Regex("z").find("abc"))
    println(Regex("b+").find("abbbc", 3)?.range)
    println(Regex("a.c").matches("abc"))
    println(Regex("a.c").matches("abcd"))
    println(Regex("a.c").containsMatchIn("xxabcxx"))
    println(Regex("a.c").matchEntire("abc")!!.value)
    println(Regex("a.c").matchEntire("abcd"))
    println(Regex("b").matchAt("abc", 1)!!.value)
    println(Regex("b").matchAt("abc", 0))
    println(Regex("b").matchesAt("abc", 1))
    println("abc" matches Regex("a.c"))
    println(Regex("a.c") in "abc")
    println("abc".contains(Regex("b")))
    // options
    println(Regex("abc", RegexOption.IGNORE_CASE).matches("aBC"))
    println(Regex("abc", setOf(RegexOption.IGNORE_CASE, RegexOption.MULTILINE)).options)
    println(Regex("^b", RegexOption.MULTILINE).findAll("a\nb\nc").count())
    println(Regex("a.b").matches("a\nb"))
    println(Regex("a.b", RegexOption.DOT_MATCHES_ALL).matches("a\nb"))
    println(Regex("a b # comment\n c", RegexOption.COMMENTS).matches("abc"))
    println(Regex("a.b", RegexOption.LITERAL).matches("a.b"))
    println(Regex("a.b", RegexOption.LITERAL).matches("axb"))
    println(Regex("(?i)abc").matches("ABC"))
    println(Regex("a(?i)bc").matches("aBC"))
    println(Regex("a(?i:b)c").matches("aBc"))
    println(Regex("a(?i:b)c").matches("aBC"))
    println(Regex("(?s)a.b").matches("a\nb"))
    println(Regex("(?m)^x$").findAll("x\ny\nx").count())
    println(Regex("abc").pattern)
    println(Regex("abc"))
    println(Regex.escape("a.b*c"))
    println(Regex.fromLiteral("a.b").matches("a.b"))
    println("a.b".toRegex().pattern)
    println("A".toRegex(RegexOption.IGNORE_CASE).matches("a"))
    println("A".toRegex(setOf(RegexOption.IGNORE_CASE)).matches("a"))
    // syntax
    println(Regex("[a-c&&[^b]]+").find("abcabc")!!.value)
    println(Regex("[^a-c]+").find("abxyc")!!.value)
    println(Regex("\\p{Alpha}+").find("12ab34")!!.value)
    println(Regex("\\p{Upper}\\p{Lower}+").find("hello World")!!.value)
    println(Regex("\\p{L}+").find("12héllo34")!!.value)
    println(Regex("\\p{Punct}").findAll("a,b.c!").count())
    println(Regex("\\d{2,3}").findAll("1 12 123 1234").map { it.value }.toList())
    println(Regex("a{2}").findAll("aaaaa").count())
    println(Regex("a+?").find("aaa")!!.value)
    println(Regex("a*+a").find("aaa"))
    println(Regex("(?>a*)a").find("aaa"))
    println(Regex("(a|ab)(c|bcd)(d*)").find("abcd")!!.groupValues)
    println(Regex("(?:ab)+").find("ababab")!!.value)
    println(Regex("^\\s*(\\w+)\\s*=\\s*(.*?)\\s*$").find("  key =  value  ")!!.groupValues)
    println(Regex("\\bcat\\b").findAll("cat concat cat.").count())
    println(Regex("\\Bcat").findAll("cat concat").count())
    println(Regex("\\Aab").find("abab")!!.range)
    println(Regex("ab\\z").find("abab")!!.range)
    println(Regex("ab\\Z").find("abab\n")!!.range)
    println(Regex("\\t\\n").matches("\t\n"))
    println(Regex("\\x41\\u0042\\0103").matches("ABC"))
    println(Regex("\\Qa.b\\E+").matches("a.bbb"))
    println(Regex("[\\w.-]+@[\\w.-]+\\.[a-z]{2,}").findAll("a.b@c.com, x@y.org").map { it.value }.toList())
    println(Regex("(\\d+)\\s*(?:px|em)").find("width: 100 px")!!.groupValues)
    println(Regex("(a)|(b)").find("b")!!.groupValues)
    println(Regex("(a)|(b)").find("b")!!.groups.map { it?.value })
    println(Regex("(?<w>\\w+) \\k<w>").find("the the cat")!!.value)
    println(Regex("^(\\d+)(?:\\.(\\d+))?$").find("12")!!.groupValues)
    for (bad in listOf("[", "(", "a{2", "*a", "(?<n>a)(?<n>b)", "\\k<zz>", "a)")) {
        try {
            Regex(bad)
            println("ok $bad")
        } catch (e: IllegalArgumentException) {
            println("bad $bad")
        }
    }
}
